import {practiceEntryCard,practiceOverviewModule} from './practice.js?v=20261014-sources1';
import {creationConsciousness} from './creation-consciousness.js?v=20261014-sources1';
import {creationTemplate} from './creation-template.js?v=20261014-sources1';
import {creationReality} from './creation-reality.js?v=20261014-sources1';
import {creationOrder,creationNames,creationLayers,creationOverview,creationCycle} from './creation-framework.js?v=20261014-sources1';
export const creationContent={...creationConsciousness,...creationTemplate,...creationReality};
export {creationOrder,creationNames,creationLayers};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const p=xs=>xs.map(x=>`<p>${esc(x)}</p>`).join('');
const fold=(q,ps)=>`<details class="action-fold dao-fold"><summary>${esc(q)}</summary><div class="action-prose">${p(ps)}</div></details>`;
const crumbs=name=>`<nav class="breadcrumbs" aria-label="当前位置"><a href="#/">首页</a><span>/</span><a href="#/ren">人道</a><span>/</span>${name?`<a href="#/becoming">创造自己</a><span>/</span><span aria-current="page">${esc(name)}</span>`:'<span aria-current="page">创造自己</span>'}</nav>`;
const toc=entries=>`<aside class="article-toc"><span class="eyebrow">本文脉络</span>${entries.map(([id,label])=>`<button type="button" data-scroll="${id}">${esc(label)}</button>`).join('')}</aside>`;
const body=(prefix,sections)=>sections.map(s=>`<h2 id="${prefix}-${s.id}">${esc(s.title)}</h2>${p(s.paragraphs)}${s.questions.map(([q,ps])=>fold(q,ps)).join('')}`).join('');
const next=(href,label,back='#/becoming',backLabel='返回创造自己')=>`<nav class="reading-next" aria-label="继续阅读"><a class="reading-next-primary" href="${href}">${label} <span aria-hidden="true">→</span></a><a class="reading-next-back" href="${back}">${backLabel}</a></nav>`;
const nameFor=id=>creationNames[creationOrder.indexOf(id)]||'创造的循环';
const matrix=()=>`<section class="creation-map" aria-label="三层九项结构"><p class="eyebrow">三层九项 / 彼此作用，持续反馈</p>${creationLayers.map(l=>`<div class="creation-map-row"><a class="creation-map-layer" href="#/becoming?layer=${l.id}"><strong>${l.name}</strong><small>${l.subtitle}</small></a><div class="creation-map-items">${l.parts.map(id=>`<a href="#/becoming/${id}"><span>${String(creationOrder.indexOf(id)+1).padStart(2,'0')}</span><strong>${nameFor(id)}</strong><span aria-hidden="true">↗</span></a>`).join('')}</div></div>`).join('')}<p class="creation-return">↶ 经验与反馈可以反向更新每一项；从眼前最需要的一处开始。</p></section>`;
const cycleGraphic=()=>`<figure class="creation-cycle"><figcaption>一条典型的实践路径</figcaption><ol>${[['觉知','看见既有模式'],['选择','明确方向与前提'],['准备','预演、聚焦与调节'],['实践','判断、表达与行动'],['反馈','核实后果，重新选择']].map(([t,s])=>`<li><strong>${t}</strong><span>${s}</span></li>`).join('')}</ol><p>↶ 反馈返回全系统；也可以从情绪、话语或一次小行动进入。</p></figure>`;
function sources(items){return `<details class="action-fold dao-fold dao-sources"><summary>思想来源与概念依据</summary><div class="action-prose"><p>本篇定义、三层九项的分工、贯穿案例与练习，由《三道哲学》组织阐释。来源思想提供对照，心理学研究只支持各自考察的具体过程，不构成对整套哲学框架的验证。</p>${items.map(s=>`<p>${s.url?`<a class="source-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`:`<strong>${esc(s.title)}</strong>`}<br>${esc(s.note)}</p>`).join('')}<p><a href="#/becoming/cases">查看贯穿案例与来源阅读说明 ↗</a></p></div></details>`;}
export function creationElementPage(id){
 const d=creationContent[id];if(!d)return '';
 const index=creationOrder.indexOf(id),layer=creationLayers[Math.floor(index/3)];
 const prefix='creation-'+id;
 const items=[[prefix+'-definition','理解'+d.name],...d.sections.map(s=>[prefix+'-'+s.id,s.title]),[prefix+'-case','同一次质疑：'+d.name+'的作用'],[prefix+'-practice','走向创造实践'],[prefix+'-bridge','继续追问']];
 return `<div class="page-shell becoming-page be-element dao-reading creation-page">${crumbs(d.name)}<header class="be-element-head"><p class="eyebrow">${layer.name} · ${layer.subtitle} / ${String(index+1).padStart(2,'0')}</p><h1>${d.name}</h1><p class="be-element-essence">${esc(d.thesis)}</p><p class="creation-question"><span>本篇追问</span>${esc(d.question)}</p></header><div class="article-layout">${toc(items)}<article class="prose"><h2 id="${prefix}-definition">理解${d.name}</h2>${p(d.definition)}${body(prefix,d.sections)}<h2 id="${prefix}-case">同一次质疑：${d.name}的作用</h2><div class="creation-case">${p(d.case)}</div><h2 id="${prefix}-practice">走向创造实践</h2>${practiceEntryCard(id)}<h2 id="${prefix}-bridge">继续追问</h2><p>${esc(d.bridge.text)}</p><p><a class="text-link" href="#/becoming/${id==='action'?'mechanism':d.bridge.next}">${id==='action'?'进入创造的循环':'继续阅读'+nameFor(d.bridge.next)} ↗</a></p>${sources(d.sources)}</article></div><nav class="be-element-footer">${next('#/becoming/'+(id==='action'?'mechanism':d.bridge.next),id==='action'?'进入创造的循环':'继续阅读：'+nameFor(d.bridge.next))}</nav></div>`;
}
export function creationOverviewPage(){
 const d=creationOverview,items=[...d.sections.map(s=>['creation-overview-'+s.id,s.title]),['creation-layers','三层如何作用与反馈'],['creation-network','九项是一张反馈网络'],['creation-opening-case','从同一次质疑开始'],['creation-practice-bridge','从理解到体验，从体验到成为']];
 return `<div class="page-shell becoming-page be-framework dao-reading creation-page">${crumbs()}<header class="be-element-head"><p class="eyebrow">人道 / 三层九项</p><h1>${d.title}</h1><p class="be-element-essence">${d.subtitle}</p><p class="be-element-intro">${d.intro}</p></header>${matrix()}<div class="article-layout">${toc(items)}<article class="prose">${body('creation-overview',d.sections)}<h2 id="creation-layers">三层如何作用与反馈</h2><p>三层分别组织自我定向、内在成形、现实运行与外化。它们不是彼此隔绝的部件，也不是必须依次完成的时间阶段。展开每一层，可以看见它处理什么、怎样影响实践、又怎样被实践更新。</p>${creationLayers.map(l=>`<section id="be-${l.id}" class="creation-layer"><details class="action-fold dao-fold"><summary>${l.name} · ${l.subtitle}</summary><div class="action-prose"><p><strong>${l.question}</strong></p><h3>从什么开始</h3><p>${l.input}</p><h3>这一层怎样工作</h3><p>${l.work}</p><h3>怎样进入下一步</h3><p>${l.forward}</p><h3>怎样接受反馈</h3><p>${l.feedback}</p><div class="creation-layer-links">${l.parts.map(id=>`<a href="#/becoming/${id}">${nameFor(id)} ↗</a>`).join('')}</div></div></details></section>`).join('')}<h2 id="creation-network">九项是一张反馈网络</h2><p>身份影响信念，新的经验也会改变身份；解释牵动情绪，情绪又影响解释；行动既表达方向，也带回原先没有的信息。按九项展开是一条教学路径，并非生命只能从第一项走到第九项。</p>${cycleGraphic()}${fold('天道中的三层，与人道中的三层是同一个机制吗？',['两处在意识、模板与实相的哲学结构上相互呼应，讨论对象却不同。天道讨论本体系如何理解经验与实相的生成；人道聚焦个体怎样定向、准备、判断、表达与实践。','此处“模板”包含熟悉的内在预演与回应模式，也包含新模式的准备。这样的实践解释不能单凭名称与结构相似，就证明意识直接操纵外部物质事件；同样，也不把天道的模板层全部缩减成一项心理学概念。'])}${fold('为什么情绪在模板层，思维却放在实相层？',['情绪放在模板层，是为了看见习惯性情绪关联怎样影响注意和行动准备，以及新回应怎样逐渐变得可承受、可练习。情绪也能先由身体或环境触发，并贯穿全部九项。','思维依旧是内在认知活动。在实相层讨论它，强调它面对具体事实作解释、判断和决策的作用，所以这一层使用“现实运行与外化”作为副标题。分工说明讨论重点，不把思想说成外部物质，也不把九项划成互不往来的区域。'])}<h2 id="creation-opening-case">从同一次质疑开始</h2><p>一位项目负责人，希望成为有独立判断力、愿意承担责任的领导者。但在方案会议上，同事一质疑关键假设，他就紧张、防御，急于证明自己正确。九篇会回到这个同一情境，分别辨认方向、内在准备、判断、表达与实践发生了什么。</p><p>这不是一个最后赢得辩论的故事。他可能发现自己错了，仍选择公开修正并承担影响。各项机制的意义，将在这次真实的取舍中变得清楚；终章再把它们连回完整的循环。</p><p><a class="text-link" href="#/becoming/identity">从身份开始阅读 ↗</a>　<a class="text-link" href="#/becoming/mechanism">先看创造的循环 ↗</a></p>${practiceOverviewModule()}${sources(d.sources||[])}</article></div>${next('#/becoming/identity','第一项：身份','#/acceptance','回看接纳自己')}</div>`;
}
export function creationCyclePage(){
 const d=creationCycle;return `<div class="page-shell becoming-page dao-reading creation-page">${crumbs(d.title)}<header class="be-element-head"><p class="eyebrow">创造自己 / 终章</p><h1>${d.title}</h1><p class="be-element-essence">${d.subtitle}</p><p class="be-element-intro">${d.intro}</p></header><div class="article-layout">${toc(d.sections.map(s=>['creation-cycle-'+s.id,s.title]))}<article class="prose">${cycleGraphic()}${body('creation-cycle',d.sections)}<p><a class="text-link" href="#/practice">进入创造实践 ↗</a></p>${sources([])}</article></div>${next('#/wang','走向王道')}</div>`;
}
export function creationSourcesPage(){
 const refs=creationOrder.flatMap(id=>(creationContent[id]?.sources||[]).map(s=>({...s,page:id})));
 return `<div class="page-shell becoming-page dao-reading creation-page">${crumbs('案例与思想来源')}<header class="be-element-head"><p class="eyebrow">创造自己 / 延伸阅读</p><h1>案例与思想来源</h1><p class="be-element-intro">同一个现实冲突，帮助理解九项的分工；不同类型的来源，为各自的论证提供依据。</p></header><div class="article-layout">${toc([['creation-sources-case','一个案例，九种作用'],['creation-sources-levels','怎样理解来源'],['creation-sources-index','逐篇延伸阅读']])}<article class="prose"><h2 id="creation-sources-case">一个案例，九种作用</h2><p>项目负责人在方案会议上被同事质疑关键假设，紧张、防御，想证明自己正确。新的方向是求真与担当。以下分别展开每一项的作用，具体经过在终章汇合。</p>${creationOrder.map(id=>fold(nameFor(id)+'：'+creationContent[id].question,creationContent[id].case)).join('')}<p><a href="#/becoming/mechanism">阅读完整的创造循环 ↗</a></p><h2 id="creation-sources-levels">怎样理解来源</h2><p>三层九项、Being的教学分法、九篇的练习和本页案例，属于三道哲学的综合组织。赛斯、细雨与《与神对话》等思想文本，在各自语境中讨论自我、选择与实相；本篇的具体定义不因此成为这些来源共同采用的原始分类。</p><p>经验研究用于理解它实际考察的过程，例如心理预演、注意、情绪或行动准备。它不能独自验证整套三层结构，更不能据此把意识直接生成物质事件写成既证事实。关于怎样生活的价值判断，也需要作为实践哲学来说明。</p>${fold('为什么保留哲学思想，也保留对实际后果的检验？',['一套世界观可以帮助人提出更深的问题，但具体判断仍需要事实，关系中的承诺仍需要对方能够理解，行动造成的影响仍需要被承担。把依据分清，使思想可以真正进入生活。','原有材料中的作者原文、细雨点评、研究报告的归纳与本网站的综合阐释，需要分别阅读。以下来源说明以可核对的标题、节次或研究范围为准，没有可靠原文时不补造引语。'])}<h2 id="creation-sources-index">逐篇延伸阅读</h2>${creationOrder.map(id=>`<details class="action-fold dao-fold dao-sources"><summary>${nameFor(id)} · 来源与阅读范围</summary><div class="action-prose">${refs.filter(s=>s.page===id).map(s=>`<p>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`:`<strong>${esc(s.title)}</strong>`}<br>${esc(s.note)}</p>`).join('')}<p><a href="#/becoming/${id}">回到${nameFor(id)}正文 ↗</a></p></div></details>`).join('')}</article></div>${next('#/practice','进入创造实践')}</div>`;
}
